package net.officefloor.hq.app.voidreason;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidVoidReason {
    public void handle(@Parameter InvalidVoidReasonException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.voidreason;

/** A void reason that cannot be added (blank, or already on the list); nothing is written. */
public class InvalidVoidReasonException extends Exception {
    public InvalidVoidReasonException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's void reasons, in the order added. */
public class LoadVoidReasons {
    public void service(@PathVariable("sheetId") String sheetId, VoidReasons reasons, ObjectResponse<List<String>> response) {
        response.send(reasons.list(sheetId));
    }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds the reason to the sheet's list. */
public class SaveVoidReason {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidVoidReason reason, VoidReasons reasons, Audit audit,
            ObjectResponse<List<String>> response) {
        reasons.add(sheetId, reason.reason());
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + reason.user() + " reason=" + reason.reason());
        response.send(reasons.list(sheetId));
    }
}
package net.officefloor.hq.app.voidreason;

import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateVoidReason {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody VoidReasonRequest request,
            Out<ValidVoidReason> body, Settings settings, VoidReasons reasons)
            throws InvalidVoidReasonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String reason = request.reason() == null ? "" : request.reason().trim();
        if (reason.isEmpty()) {
            throw new InvalidVoidReasonException("A void reason cannot be blank");
        }
        if (reasons.contains(sheetId, reason)) {
            throw new InvalidVoidReasonException("The reason is already on the list");
        }
        body.set(new ValidVoidReason(reason, request.user()));
    }
}
package net.officefloor.hq.app.voidreason;

/** A void reason that passed validation: trimmed, not blank and not yet on the sheet's list. */
public record ValidVoidReason(String reason, String user) {
}
package net.officefloor.hq.app.voidreason;

/** Body of POST /api/sheets/{sheetId}/void-reasons: the reason to add to the sheet's list. */
public record VoidReasonRequest(String reason, String user) {
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The void reason store: the reasons on each sheet's list, in the order added. */
@Repository
public class VoidReasons {

    private final JdbcTemplate jdbc;

    public VoidReasons(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's void reasons, in the order added. */
    public List<String> list(String sheetId) {
        return jdbc.queryForList("SELECT reason FROM void_reason WHERE sheet_id = ? ORDER BY seq", String.class, sheetId);
    }

    /** Whether the reason is on the sheet's list. */
    public boolean contains(String sheetId, String reason) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM void_reason WHERE sheet_id = ? AND reason = ?",
                Integer.class, sheetId, reason);
        return n != null && n > 0;
    }

    /** Adds the reason to the sheet's list. */
    public void add(String sheetId, String reason) {
        jdbc.update("INSERT INTO void_reason (sheet_id, reason) VALUES (?, ?)", sheetId, reason);
    }
}
